@js:
var result = [];

var genderMap = {
    "男生": "male",
    "女生": "female"
};

var genderType = infoMap["性别"] || "男生";
var genderParam = genderMap[genderType];

// 性别选择器（权重1，独占一行）
result.push({
    "title": "性别",
    "type": "select",
    "chars": ["男生", "女生"],
    "default": genderType,
    "action": "java.refreshExplore()",
    "style": {"layout_flexGrow": 1, "layout_flexBasisPercent": 1}
});

// 当前性别的"全部"入口（权重1）
result.push({
    "title": genderType + "·全部",
    "url": "/all/0;0;" + genderParam + ";;;H;{{page}}.html",
    "style": {"layout_flexGrow": 1, "layout_flexBasisPercent": 1}
});

// 6个分类（权重0.25，4个一行）
var cats = [
    ["都市", "Z1B"],
    ["战争", "5pAB"],
    ["穿越", "eKk4"],
    ["搞笑", "pVj"],
    ["家庭", "5pXm"],
    ["悬疑", "qdW"]
];
for (var i = 0; i < cats.length; i++) {
    result.push({
        "title": cats[i][0],
        "url": "/all/0;" + cats[i][1] + ";" + genderParam + ";;;H;{{page}}.html",
        "style": {"layout_flexGrow": 1, "layout_flexBasisPercent": 0.25}
    });
}

JSON.stringify(result);
